// Application-owned local handler for Prompt 40.
// s is the lesson state; p contains validated classroom controls.
switch (action.op) {
    case 'events.pages':
        r.history = Array.from({ length: 5 }, (_, i) => ({ id: `evt-${i}`, type: i ? 'processing' : 'submitted' }));
        s.rows = r.history;
        accept({ pages: [r.history.slice(0, 2), r.history.slice(2, 4), r.history.slice(4)], next_page: null });
        break;
}
